{"command":"python3 -c "
notes = ['C-', 'C#', 'D-', 'D#', 'E-', 'F-', 'F#', 'G-', 'G#', 'A-', 'A#', 'B-']
def note_to_num(name):
    # e.g. 'C-4' -> 49, 'D#3' -> 39, 'A-4' -> 58
    n = name[:2]
    octave = int(name[2])
    idx = notes.index(n)
    return 1 + octave * 12 + idx

# Test some notes:
for test_n in ['C-2', 'Eb2', 'C-4', 'D-4', 'Eb4', 'F-4', 'G-4', 'Ab4', 'Bb4', 'C-5']:
    alt = test_n.replace('b', '#')
    # wait, Eb is D#, Ab is G#, Bb is A#
    mapping = {'Eb': 'D#', 'Bb': 'A#', 'Ab': 'G#', 'Db': 'C#', 'Gb': 'F#'}
    lookup = test_n
    for k, v in mapping.items():
        lookup = lookup.replace(k, v)
    if len(lookup) == 3 and lookup[1] != '#':
        lookup = lookup[0] + '-' + lookup[2]
    print(f'{test_n:5s} -> {lookup:5s} -> {note_to_num(lookup)}')
""}
